PRAGMA foreign_keys=ON; CREATE TABLE conversations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,kind TEXT NOT NULL); CREATE TABLE conversation_members(conversation_id TEXT REFERENCES conversations(id),user_id TEXT NOT NULL,PRIMARY KEY(conversation_id,user_id)); CREATE TABLE messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL,sender_id TEXT NOT NULL,parent_id TEXT REFERENCES messages(id),body TEXT NOT NULL,edited_at TEXT,deleted_at TEXT,created_at TEXT NOT NULL,FOREIGN KEY(conversation_id,sender_id) REFERENCES conversation_members(conversation_id,user_id)); CREATE TABLE read_markers(conversation_id TEXT NOT NULL,user_id TEXT NOT NULL,last_message_id TEXT,updated_at TEXT NOT NULL,PRIMARY KEY(conversation_id,user_id),FOREIGN KEY(conversation_id,user_id) REFERENCES conversation_members(conversation_id,user_id)); CREATE TABLE file_stages(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,path TEXT NOT NULL,content_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,expires_at TEXT NOT NULL,finalized_at TEXT); CREATE TABLE email_outbox(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,dedupe_key TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TEXT,payload_json TEXT NOT NULL,UNIQUE(user_id,dedupe_key));
